-- Darumi: актуалізація офіційних варіантів з sitemap виробника.
-- 426 актуальних виконань для 35 наявних моделей. Carmen не додається: знято з виробництва.
-- Змінюються тільки опції, варіанти фото та офіційні джерела Darumi.
-- Товари, описи, характеристики, головні фото і статус публікації не змінюються.
begin;
delete from public.product_options where product_slug in (select slug from public.products where brand = 'Darumi');
delete from public.product_variants where product_slug in (select slug from public.products where brand = 'Darumi');


commit;

select count(*) as active_darumi_variants from public.product_variants where product_slug in (select slug from public.products where brand = 'Darumi') and is_active=true;
select count(*) as darumi_options from public.product_options where product_slug in (select slug from public.products where brand = 'Darumi') and is_active=true;
